const ic=(name,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[name]||ICONS.info}</svg>`;
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(s)=>s?new Intl.DateTimeFormat('es-CL',{day:'2-digit',month:'short',year:'numeric'}).format(new Date(`${s}T12:00:00`)):'Sin fecha';
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const deltaDays=date=>Math.round((new Date(`${date}T12:00:00`).getTime()-new Date(`${today()}T12:00:00`).getTime())/86400000);
const bytes=n=>n>=1048576?(n/1048576).toFixed(1)+' MB':Math.max(1,Math.round(n/1024))+' KB';
const uid=()=>globalThis.crypto?.randomUUID?.()||`id-${Date.now()}-${Math.random().toString(36).slice(2)}`;
const root=document.querySelector('#mainContent');
const documentThumbnails=new Map();
function documentThumb(d){if(!d?.blob||!(/image\//i.test(d.mime||'')||/\.(png|jpg|jpeg|webp)$/i.test(d.filename||'')))return '';let src=documentThumbnails.get(d.id);if(!src){src=URL.createObjectURL(d.blob);documentThumbnails.set(d.id,src);}return `<img class="doc-thumb" src="${src}" alt="Miniatura de ${escapeHTML(d.filename)}" loading="lazy">`;} 
let previewURL='';
function clearPreview(){if(previewURL){URL.revokeObjectURL(previewURL);previewURL='';}document.querySelector('#previewRoot').innerHTML='';}
function showBlobPreview(blob,name,mime){clearPreview();if(!blob){toast('No existe una copia del archivo.',true);return;}previewURL=URL.createObjectURL(blob);const typ=mime||blob.type||'';const pdf=typ.includes('pdf')||/\.pdf$/i.test(name);const img=typ.startsWith('image/')||/\.(png|jpe?g|webp)$/i.test(name);const safe=escapeHTML(name);const media=img?`<img class="doc-preview-image" src="${previewURL}" alt="Documento ${safe}">`:pdf?`<iframe class="doc-preview-pdf" title="PDF ${safe}" src="${previewURL}#toolbar=1"></iframe>`:`<div class="preview-empty">Vista integrada no disponible para este formato. Utiliza Descargar archivo.</div>`;document.querySelector('#previewRoot').innerHTML=`<div class="preview-overlay" role="dialog" aria-modal="true" aria-label="Vista previa"><div class="preview-sheet"><header><div><strong>Documento original</strong><small>${safe}</small></div><button class="close-btn" type="button" data-action="close-preview" aria-label="Cerrar vista previa">${ic('x')}</button></header><div class="preview-content">${media}</div><footer><a class="btn btn-primary" href="${previewURL}" download="${safe}">${ic('download')} Descargar original</a><button class="btn btn-secondary" type="button" data-action="close-preview">Cerrar</button></footer></div></div>`;}

const state={vehicles:[],docs:[],fuelLogs:[],expenses:[],selected:'',tab:'inicio',search:'',typeFilter:'all',uploadFiles:[],analyses:[],processing:false,scanToken:0,uploadTarget:'',confirm:null};
const names={inicio:'Panel general',vehiculos:'Mis vehículos',documentos:'Documentos',combustible:'Combustible y recargas',gastos:'Gastos y presupuesto',vencimientos:'Vencimientos',respaldo:'Respaldo y privacidad'};

function openDB(){return new Promise((resolve,reject)=>{const request=indexedDB.open('SNK_GARAGE_DB',2);request.onupgradeneeded=()=>{const db=request.result;if(!db.objectStoreNames.contains('vehicles'))db.createObjectStore('vehicles',{keyPath:'id'});if(!db.objectStoreNames.contains('docs')){const s=db.createObjectStore('docs',{keyPath:'id'});s.createIndex('vehicleId','vehicleId');}for(const name of ['fuelLogs','expenses']){if(!db.objectStoreNames.contains(name)){const s=db.createObjectStore(name,{keyPath:'id'});s.createIndex('vehicleId','vehicleId');}}};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});}
let db;
function transaction(store,method,value){return new Promise((resolve,reject)=>{const tx=db.transaction(store,'readwrite');const request=tx.objectStore(store)[method](value);request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});}
function all(store){return new Promise((resolve,reject)=>{const tx=db.transaction(store,'readonly');const req=tx.objectStore(store).getAll();req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
async function reload(){state.vehicles=(await all('vehicles')).sort((a,b)=>String(b.updatedAt||'').localeCompare(String(a.updatedAt||'')));state.docs=(await all('docs')).sort((a,b)=>String(b.uploadedAt||'').localeCompare(String(a.uploadedAt||'')));state.fuelLogs=(await all('fuelLogs')).sort((a,b)=>String(b.date||'').localeCompare(String(a.date||''))||String(b.createdAt||'').localeCompare(String(a.createdAt||'')));state.expenses=(await all('expenses')).sort((a,b)=>String(b.date||'').localeCompare(String(a.date||''))||String(b.createdAt||'').localeCompare(String(a.createdAt||'')));if(!state.vehicles.find(v=>v.id===state.selected))state.selected=state.vehicles[0]?.id||'';try{localStorage.setItem('snk-garage-active',state.selected);}catch{}render();}
const vehicle=()=>state.vehicles.find(x=>x.id===state.selected);
const vDocs=(id=state.selected)=>state.docs.filter(d=>d.vehicleId===id);
const vFuel=(id=state.selected)=>state.fuelLogs.filter(d=>d.vehicleId===id);
const vExpenses=(id=state.selected)=>state.expenses.filter(d=>d.vehicleId===id);
const docState=d=>{if(!d)return{label:'Sin documento',tone:'neutral',days:null};if(!d.expires)return{label:'Sin vencimiento registrado',tone:'neutral',days:null};const days=deltaDays(d.expires);return days<0?{label:'Vencido',tone:'bad',days}:days<=30?{label:'Vence pronto',tone:'warn',days}:{label:'Vigente',tone:'good',days};};
const newestOf=(type,id=state.selected)=>vDocs(id).filter(d=>d.type===type).sort((a,b)=>(b.expires||b.uploadedAt||'').localeCompare(a.expires||a.uploadedAt||''))[0];
const totals=()=>{const docs=state.selected?vDocs():state.docs;return{cars:state.vehicles.length,docs:docs.length,expired:docs.filter(d=>docState(d).tone==='bad').length,soon:docs.filter(d=>docState(d).tone==='warn').length};};
function toast(message,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=message;document.querySelector('#toastArea').append(el);setTimeout(()=>el.remove(),5600);}
function decorate(node=document){node.querySelectorAll('[data-icon]').forEach(el=>{if(!el.querySelector('svg'))el.innerHTML=ic(el.dataset.icon);});}
function setTab(tab){if(!names[tab])return;closeMore();state.tab=tab;state.search='';state.typeFilter='all';render();window.scrollTo({top:0,behavior:'smooth'});}
function closeMore(){const menu=document.querySelector('#mobileMoreMenu');if(menu)menu.hidden=true;const button=document.querySelector('#moreButton');if(button)button.setAttribute('aria-expanded','false');}
function toggleMore(){const menu=document.querySelector('#mobileMoreMenu');if(!menu)return;menu.hidden=!menu.hidden;const button=document.querySelector('#moreButton');if(button)button.setAttribute('aria-expanded',String(!menu.hidden));}
function applyTheme(theme){const value=theme==='light'?'light':'dark';document.documentElement.dataset.theme=value;document.querySelector('meta[name="theme-color"]')?.setAttribute('content',value==='light'?'#f0f2f4':'#111820');try{localStorage.setItem('snk-garage-theme',value);}catch{}}
function render(){
 document.querySelector('#pageCrumb').textContent=names[state.tab];document.querySelector('#navVehicleCount').textContent=state.vehicles.length;
 const select=document.querySelector('#vehicleSelect');select.innerHTML=state.vehicles.length?state.vehicles.map(v=>`<option value="${escapeHTML(v.id)}">${escapeHTML(v.plate||'Sin patente')} · ${escapeHTML(v.brand||'Auto')}</option>`).join(''):'<option value="">Sin vehículos</option>';select.value=state.selected||'';
 document.querySelectorAll('[data-nav]').forEach(btn=>{const active=btn.dataset.nav===state.tab;btn.classList.toggle('active',active);if(active)btn.setAttribute('aria-current','page');else btn.removeAttribute('aria-current');});
 const more=document.querySelector('#moreButton');if(more)more.classList.toggle('active',['gastos','vencimientos','respaldo'].includes(state.tab));
 root.innerHTML=({inicio:renderHome,vehiculos:renderGarage,documentos:renderDocuments,combustible:renderFuel,gastos:renderExpenses,vencimientos:renderExpiry,respaldo:renderBackup}[state.tab])();
 decorate();
}
const stat=(label,n,desc,icon,tone='')=>`<div class="stat-card ${tone}"><div class="stat-label">${label}<span>${ic(icon,19)}</span></div><div class="stat-number">${n}</div><div class="stat-foot">${desc}</div></div>`;
const carSVG=`<svg viewBox="0 0 320 166" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><path d="m29 112 28-13 23-44a27 27 0 0 1 23-14h108a39 39 0 0 1 30 14l35 39 23 18-3 24H25z" fill="#dfc19a" opacity=".88"/><path d="m91 58-17 38h78V58H91zm76 0v38h88l-27-32a17 17 0 0 0-14-6z" fill="#16232a"/><path d="M58 137h242M35 115h25m198 0h21" stroke="#1b2b21" stroke-width="5" stroke-linecap="round"/><circle cx="89" cy="135" r="24" fill="#22312c"/><circle cx="89" cy="135" r="12" fill="#a79076"/><circle cx="249" cy="135" r="24" fill="#22312c"/><circle cx="249" cy="135" r="12" fill="#a79076"/><path d="M31 115v12h14v-14" fill="#ebe5da"/><path d="M277 114v12h17v-11" fill="#f6c981"/></svg>`;
const empty=(title,desc,label,action='new-car',icon='car')=>`<div class="empty-state"><div class="empty-icon">${ic(icon,38)}</div><h3>${title}</h3><p>${desc}</p><button class="btn btn-primary" data-action="${action}">${ic('plus')} ${label}</button></div>`;
function renderHome(){
 const v=vehicle(),d=v?vDocs():[],t=totals();
 const month=v?periodSummary(state.fuelLogs,state.expenses,v.id,today().slice(0,7)):null;
 const expiring=v?d.filter(doc=>['bad','warn'].includes(docState(doc).tone)):[];
 const hero=v?`<section class="hero home-hero" aria-label="Ficha principal de vehículo">
  <div class="hero-inner"><div class="eyebrow">VEHÍCULO ACTIVO · CHILE</div>
  <div class="plate-hero-row"><div class="license"><small>REPÚBLICA DE CHILE</small><strong>${escapeHTML(v.plate)}</strong><span>CHILE</span></div>
  <div class="hero-desc"><strong>${escapeHTML([v.brand,v.model,v.version].filter(Boolean).join(' ')||'Tu vehículo')}</strong>
   <small>${escapeHTML(v.year||'Año sin registrar')} · ${escapeHTML(v.color||'Color por registrar')}</small>
   <div class="hero-badges"><span class="hero-pill">${ic('fuel',13)} ${escapeHTML(fuelName(v.fuelGrade))}</span>${v.mileage?`<span class="hero-pill">${escapeHTML(v.mileage)} km</span>`:''}</div>
  </div></div><p>Ten a mano los datos de tu auto, sus archivos, el combustible que utilizas y lo que gastas en mantenerlo.</p>
  <div class="hero-actions"><button class="btn btn-primary" data-action="fuel-new">${ic('plus')} Registrar carga</button><button class="btn btn-secondary" data-action="open-upload">${ic('upload')} Adjuntar documento</button><button class="btn btn-secondary" data-action="edit-car" data-id="${escapeHTML(v.id)}">${ic('edit')} Editar ficha</button></div></div>
 </section>`:`<section class="hero home-hero hero-empty"><div class="hero-inner"><div class="eyebrow">SNK GARAGE · TU CENTRO VEHICULAR</div><h1>Todo sobre tu auto, <span>en un lugar.</span></h1><p>Comienza con una patente o con un documento. Después podrás administrar el padrón, SOAP, revisión, cargas de bencina y gastos.</p><div class="hero-actions"><button class="btn btn-primary" data-action="new-car">${ic('plus')} Registrar mi auto</button><button class="btn btn-secondary" data-action="open-upload">${ic('upload')} Subir y leer documento</button></div></div></section>`;
 const summary=v?`<div class="stats-grid">${stat('Gasto en bencina este mes',money(month.fuelCLP),`${month.fillCount} recarga(s)`,'fuel')}${stat('Otros gastos del mes',money(month.otherCLP),'Sin duplicar combustible','wallet')}${stat('Documentos guardados',d.length,'De este vehículo','file')}${stat('Vencen / vencidos',expiring.length,'Revisa sus fechas','calendar',expiring.length?'warn':'')}</div>`:
 `<div class="stats-grid">${stat('Vehículos',0,'Registra el primero','car')}${stat('Documentos',0,'PDF o imágenes','file')}${stat('Cargas',0,'Litros y pesos','fuel')}${stat('Gastos',money(0),'Control mensual','wallet')}</div>`;
 const cards=v?`<div class="split-grid">
 <section class="panel"><div class="panel-top"><h3>Documentos esenciales</h3><button class="text-link" data-nav="documentos">Ver archivos ${ic('arrow',14)}</button></div>
 ${['padron','permiso','revision','soap','emisiones'].map(type=>{const doc=newestOf(type);const ds=docState(doc);return `<div class="document-row"><div class="doc-icon">${ic('file')}</div><div class="document-row-main"><strong class="document-row-title">${escapeHTML(docLabel(type))}</strong><small class="document-row-sub">${doc?(doc.expires?'Vence '+fmt(doc.expires):'Adjuntado'):'Pendiente de adjuntar'}</small></div><span class="status ${doc?ds.tone:'neutral'}">${doc?ds.label:'Sin archivo'}</span></div>`}).join('')}
 <button class="btn btn-secondary" style="margin-top:15px;width:100%" data-action="open-upload">${ic('plus')} Agregar documento</button></section>
 <section class="panel"><div class="panel-top"><h3>Ficha y finanzas</h3><button class="text-link" data-nav="gastos">Ver detalle ${ic('arrow',14)}</button></div>
 <div class="detail-pairs"><div><span class="key">Marca y modelo</span><span class="val">${escapeHTML([v.brand,v.model].filter(Boolean).join(' ')||'No informado')}</span></div>
 <div><span class="key">Año</span><span class="val">${escapeHTML(v.year||'No informado')}</span></div>
 <div><span class="key">Combustible registrado</span><span class="val">${escapeHTML(fuelName(v.fuelGrade))}</span></div>
 <div><span class="key">VIN / N° serie</span><span class="val">${escapeHTML(v.vin||'No informado')}</span></div>
 <div><span class="key">Motor</span><span class="val">${escapeHTML(v.engine||'No informado')}</span></div>
 <div><span class="key">Gasto total del mes</span><span class="val">${money(month.total)}</span></div></div>
 <div class="hero-actions" style="display:flex;gap:9px;flex-wrap:wrap;margin-top:20px"><button class="btn btn-secondary" data-nav="combustible">${ic('fuel')} Combustible</button><button class="btn btn-secondary" data-nav="gastos">${ic('wallet')} Finanzas</button></div></section>
 </div>`:'';
 return `${hero}${summary}${cards}${v&&d.length?`<div class="section-head"><h2 class="section-title">Archivos recientes</h2><button class="text-link" data-nav="documentos">Todos los documentos ${ic('arrow',13)}</button></div><div class="file-table">${d.slice(0,3).map(docCard).join('')}</div>`:''}`;
}
function renderGarage(){return `<div class="page-head"><div><div class="eyebrow">INVENTARIO</div><h1 class="page-title">Mis vehículos</h1><p class="page-copy">Administra las fichas de todos tus vehículos y cambia entre ellos cuando lo necesites.</p></div><div class="page-head-actions"><button class="btn btn-primary" data-action="new-car">${ic('plus')} Agregar vehículo</button></div></div>${state.vehicles.length?`<div class="garage-grid">${state.vehicles.map(v=>{const c=vDocs(v.id).length;return `<article class="garage-card ${v.id===state.selected?'selected':''}"><div class="vehicle-preview"><div class="vehicle-avatar">${ic('car',38)}</div><div><h3>${escapeHTML([v.brand,v.model].filter(Boolean).join(' ')||'Mi vehículo')}</h3><span class="plate-tag">${escapeHTML(v.plate)}</span></div></div><div class="vehicle-meta"><span>Año <strong>${escapeHTML(v.year||'—')}</strong></span><span>Color <strong>${escapeHTML(v.color||'—')}</strong></span><span>${c} archivo(s)</span><span>${escapeHTML(fuelName(v.fuelGrade))}</span></div><div class="garage-card-bottom"><button class="btn btn-sm ${v.id===state.selected?'btn-primary':'btn-secondary'}" data-action="select-car" data-id="${escapeHTML(v.id)}">${v.id===state.selected?'Seleccionado':'Seleccionar'}</button><div class="actions"><button class="icon-action" data-action="edit-car" data-id="${escapeHTML(v.id)}" aria-label="Editar vehículo">${ic('edit')}</button><button class="icon-action" data-action="delete-car" data-id="${escapeHTML(v.id)}" aria-label="Eliminar vehículo">${ic('trash')}</button></div></div></article>`;}).join('')}</div>`:empty('Tu garaje está vacío','Registra una patente y los datos de un automóvil para empezar a ordenar su documentación.','Registrar vehículo')}`;}
function docCard(d){const status=docState(d);const v=state.vehicles.find(x=>x.id===d.vehicleId);return `<article class="file-card"><div class="doc-icon doc-cover">${documentThumb(d)||ic('file',22)}</div><div class="file-card-content"><strong>${escapeHTML(d.title||docLabel(d.type))}</strong><small>${escapeHTML(d.filename)} · ${bytes(d.size||0)} · ${escapeHTML(v?.plate||'Sin patente')} ${d.expires?' · Vence '+fmt(d.expires):''}</small></div><span class="status ${status.tone}">${status.label}</span><div class="file-card-actions"><button class="btn btn-secondary btn-sm doc-view-button" data-action="open-doc" data-id="${escapeHTML(d.id)}" aria-label="Ver ${escapeHTML(d.filename)}">${ic('external',15)} Ver archivo</button><button class="icon-action" data-action="edit-doc" data-id="${escapeHTML(d.id)}" title="Editar" aria-label="Editar documento">${ic('edit')}</button><button class="icon-action" data-action="delete-doc" data-id="${escapeHTML(d.id)}" title="Eliminar" aria-label="Eliminar documento">${ic('trash')}</button></div></article>`;}
function renderDocuments(){const list=vDocs().filter(d=>(state.typeFilter==='all'||d.type===state.typeFilter)&&`${d.filename} ${d.title} ${docLabel(d.type)}`.toLowerCase().includes(state.search.toLowerCase()));return `<div class="page-head"><div><div class="eyebrow">ARCHIVO DIGITAL</div><h1 class="page-title">Documentos</h1><p class="page-copy">Guarda documentos originales con sus fechas. El archivo permanece en tu navegador, sin enviarse a un servidor de SNK Garage.</p></div><div class="page-head-actions"><button class="btn btn-primary" data-action="open-upload">${ic('upload')} Subir documentos</button></div></div>${!vehicle()?empty('Agrega un vehículo primero','Puedes crear una ficha manualmente o usar el reconocimiento de un padrón para darlo de alta.','Crear vehículo'):`<div class="filter-bar"><input id="docSearch" class="search-input" value="${escapeHTML(state.search)}" placeholder="Buscar por documento o archivo..." aria-label="Buscar documentos"/><select id="docTypeFilter" class="filter-select" aria-label="Filtrar por tipo"><option value="all">Todos los tipos</option>${DOC_TYPES.map(t=>`<option value="${t.value}" ${state.typeFilter===t.value?'selected':''}>${t.label}</option>`).join('')}</select></div>${list.length?`<div class="file-table">${list.map(docCard).join('')}</div>`:empty('No hay documentos para mostrar','Adjunta fotografías, PDF o archivos TXT y reconoce sus datos cuando sea posible.','Subir archivo','open-upload','file')}`}`;}
function renderExpiry(){const entries=[];for(const v of state.vehicles){for(const d of vDocs(v.id)){if(d.expires)entries.push({...d,v});}}entries.sort((a,b)=>a.expires.localeCompare(b.expires));const missing=vehicle()?['permiso','revision','soap'].filter(t=>!newestOf(t)).length:0;return `<div class="page-head"><div><div class="eyebrow">CONTROL DE VIGENCIA</div><h1 class="page-title">Vencimientos</h1><p class="page-copy">Fechas registradas en tus documentos. Las alertas se muestran al abrir la web, no son notificaciones automáticas externas.</p></div><div class="page-head-actions"><button class="btn btn-secondary" data-action="open-upload">${ic('plus')} Agregar comprobante</button></div></div>${state.vehicles.length?`<div class="stats-grid">${stat('Documentos con fecha',entries.length,'En todos tus vehículos','calendar')}${stat('Vencidos',entries.filter(x=>deltaDays(x.expires)<0).length,'Necesitan renovación','alert','bad')}${stat('Próximos 30 días',entries.filter(x=>deltaDays(x.expires)>=0&&deltaDays(x.expires)<=30).length,'Atención preventiva','clock','warn')}${stat('Sin archivo esencial',missing,'En el vehículo activo','file')}</div>${entries.length?`<div class="milestone-list">${entries.map(d=>{const status=docState(d);return `<div class="milestone"><div class="doc-icon">${ic('calendar')}</div><div class="milestone-left"><strong>${escapeHTML(docLabel(d.type))} · ${escapeHTML(d.v.plate)}</strong><small>${escapeHTML([d.v.brand,d.v.model].filter(Boolean).join(' '))} · ${escapeHTML(d.filename)}</small></div><span class="status ${status.tone}">${status.days<0?`${Math.abs(status.days)} días de atraso`:status.days===0?'Vence hoy':`${status.days} días restantes`}</span><div class="milestone-date">${fmt(d.expires)}<small>Vencimiento</small></div><button class="icon-action" data-action="open-doc" data-id="${escapeHTML(d.id)}" aria-label="Ver comprobante">${ic('external')}</button></div>`;}).join('')}</div>`:empty('Todavía no hay fechas','Ingresa la fecha de vencimiento de tus documentos al adjuntarlos o editarlos.','Adjuntar documento','open-upload','calendar')}`:empty('Sin vehículos registrados','Registra al menos un vehículo para consultar sus plazos documentales.','Crear vehículo')}`;}
function renderBackup(){return `<div class="page-head"><div><div class="eyebrow">SEGURIDAD DE DATOS</div><h1 class="page-title">Respaldo y privacidad</h1><p class="page-copy">Todo se guarda en la base de datos del navegador de este dispositivo. No hay cuenta, nube ni sincronización automática.</p></div></div><div class="tip">${ic('shield')}<div><strong>Privado por diseño.</strong> Los PDF e imágenes se almacenan en IndexedDB local. El OCR se ejecuta en tu dispositivo, pero necesita descargar bibliotecas y modelos desde internet la primera vez. Evita borrar los datos del sitio sin exportar antes una copia.</div></div><div class="backup-grid"><div class="backup-panel"><div class="empty-icon">${ic('download',28)}</div><h3>Exportar respaldo</h3><p>Descarga un archivo JSON con las fichas, documentos originales, recargas, gastos y fechas, para recuperarlos en otro navegador o dispositivo.</p><button class="btn btn-primary" data-action="export">${ic('download')} Exportar mis datos</button></div><div class="backup-panel"><div class="empty-icon">${ic('upload',28)}</div><h3>Importar respaldo</h3><p>Incorpora vehículos y archivos de una copia anterior. Se agregarán como nuevos registros para evitar reemplazar los existentes.</p><button class="btn btn-secondary" data-action="import">${ic('upload')} Importar copia</button><input id="backupInput" type="file" accept=".json,application/json" hidden /></div></div><div class="section-head"><h2 class="section-title">Qué puede y qué no puede hacer</h2></div><div class="panel small-list"><div><strong>Puede:</strong> guardar PDF/fotos, reconocer datos impresos, registrar patente, octanaje recomendado ingresado, recargas y sus precios, gastos, kilómetros y vencimientos al abrir la aplicación.</div><div><strong>No puede:</strong> acreditar automáticamente si un seguro o permiso está vigente en un registro público, buscar propietario/multas/deudas desde una patente, ni confirmar legalmente los datos extraídos.</div><div><strong>Consulta externa:</strong> <a class="accent-text" href="https://patenteschile.cl/" target="_blank" rel="noopener noreferrer">Patentes Chile ${ic('external',13)}</a> y <a class="accent-text" href="https://www.chileatiende.gob.cl/fichas/3412" target="_blank" rel="noopener noreferrer">certificado de inscripción en ChileAtiende ${ic('external',13)}</a>. Estas páginas no están integradas a SNK Garage.</div></div>`;}

function modalShell(title,description,body,footer='',small=false){closeMore();document.querySelector('#modalRoot').innerHTML=`<div class="modal-overlay" id="modalOverlay"><div class="modal ${small?'modal-sm':''}" role="dialog" aria-modal="true" aria-label="${escapeHTML(title)}"><div class="modal-head"><div><div class="eyebrow">SNK GARAGE</div><h2>${escapeHTML(title)}</h2><p>${escapeHTML(description)}</p></div><button class="close-btn" data-action="close-modal" aria-label="Cerrar">${ic('x')}</button></div>${body}${footer}</div></div>`;}
function closeModal(){clearPreview();if(state.processing){toast('Termina el reconocimiento antes de cerrar.');return;}document.querySelector('#modalRoot').innerHTML='';state.uploadFiles=[];state.analyses=[];}
function vehicleForm(v={}){const fields=[['plate','Patente *','text','Ej. ABCD12'],['brand','Marca','text','Chevrolet'],['model','Modelo','text','Sail'],['version','Versión','text','LT 1.4'],['year','Año','number','2013'],['kind','Tipo','text','Automóvil'],['color','Color','text','Gris'],['fuel','Tipo de combustible','text','Gasolina / Diésel / híbrido'],['transmission','Transmisión','text','Manual'],['fuelGrade','Bencina o energía que utiliza','select',''],['vin','VIN / Número de serie','text','17 caracteres'],['chassis','Número de chasis','text',''],['engine','Número de motor','text',''],['displacement','Cilindrada','text','1.400 cc'],['mileage','Kilometraje','text',''],['owner','Propietario','text','Opcional'],['rut','RUT propietario','text','Opcional']];const inputs=(ar)=>ar.map(([k,label,type,placeholder])=>`<div class="form-group ${['vin','chassis','engine','owner'].includes(k)?'':''}"><label for="v_${k}">${label}</label>${k==='fuelGrade'?`<select id="v_fuelGrade" name="fuelGrade"><option value="">No indicado / revisar manual</option>${FUEL_GRADES.map(t=>`<option value="${t.value}" ${t.value===v.fuelGrade?'selected':''}>${t.label}</option>`).join('')}</select>`:`<input id="v_${k}" name="${k}" type="${type}" placeholder="${escapeHTML(placeholder)}" value="${escapeHTML(v[k]||'')}" ${k==='plate'?'required maxlength="8"':'maxlength="120"'} ${k==='year'?'min="1900" max="2100"':''}/>`}</div>`).join('');return `<form id="vehicleForm"><div class="modal-body"><div class="lookup-panel"><div><strong>${ic('search',17)} Consultar patente (experimental)</strong><p>Busca marca y modelo en antecedentes de revisiones técnicas disponibles en un servicio externo. Puede no encontrar tu vehículo.</p></div><div class="lookup-actions"><button class="btn btn-secondary" type="button" data-action="lookup-car">${ic('search')} Consultar patente</button></div><p id="lookupResult" role="status" aria-live="polite"></p></div><h3 class="form-section-title">Identificación del vehículo</h3><div class="form-grid">${inputs(fields.slice(0,10))}</div><div class="banner-muted fuel-note">El octanaje (93, 95 o 97) no se obtiene de forma fiable desde la patente o el padrón. Registra el que indique el manual del vehículo o la tapa de combustible.</div><h3 class="form-section-title">Datos técnicos y propietario</h3><div class="form-grid">${inputs(fields.slice(10))}</div><h3 class="form-section-title">Presupuesto mensual (opcional)</h3><div class="form-grid two"><div class="form-group"><label for="fuelBudget">Tope mensual de combustible (CLP)</label><input id="fuelBudget" name="fuelBudget" type="number" min="0" step="1" value="${escapeHTML(v.fuelBudget||'')}" placeholder="80000"/></div><div class="form-group"><label for="totalBudget">Tope mensual total del auto (CLP)</label><input id="totalBudget" name="totalBudget" type="number" min="0" step="1" value="${escapeHTML(v.totalBudget||'')}" placeholder="120000" /></div></div><div class="form-group"><label for="v_notes">Notas propias</label><textarea name="notes" id="v_notes" placeholder="Observaciones, mantenimiento, detalles...">${escapeHTML(v.notes||'')}</textarea></div></div><div class="modal-foot">${v.id?`<button class="btn btn-danger btn-sm" data-action="delete-car" data-id="${escapeHTML(v.id)}" type="button">${ic('trash')} Eliminar</button>`:'<span class="tiny muted">* Campo obligatorio</span>'}<div class="modal-foot-right"><button type="button" class="btn btn-secondary" data-action="close-modal">Cancelar</button><button class="btn btn-primary" type="submit">${ic('save')} Guardar ficha</button></div></div></form>`;}
function showVehicleModal(id){const v=state.vehicles.find(x=>x.id===id)||{};modalShell(v.id?'Editar vehículo':'Registrar vehículo','Completa o corrige los datos de la ficha. Los campos personales son opcionales.',vehicleForm(v));document.querySelector('#vehicleForm').dataset.id=v.id||'';}
async function lookupPlate(){
 const plate=cleanPlate(document.querySelector('#v_plate')?.value||'');const out=document.querySelector('#lookupResult');
 if(!out)return;if(!validPlate(plate)){out.textContent='Primero escribe una patente válida en la ficha (por ejemplo, BBBB16).';return;}
 out.textContent='Consultando antecedentes públicos de revisión técnica…';
 const btn=document.querySelector('[data-action="lookup-car"]');if(btn)btn.disabled=true;
 const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),13000);
 try{
  // api.restart.cl documenta /v1/vehiculos-revisiones/{placa} sin autenticación.
  // CORS, disponibilidad y cobertura dependen exclusivamente del proveedor.
  const res=await fetch(`https://api.restart.cl/v1/vehiculos-revisiones/${encodeURIComponent(plate)}`,{signal:controller.signal,headers:{'Accept':'application/json'}});
  if(!res.ok)throw Error('El servicio respondió '+res.status);
  const json=await res.json();const entries=Array.isArray(json.data)?json.data:Array.isArray(json)?json:(json.data?[json.data]:[]);
  const latest=entries.map(e=>e?.attributes||e).filter(x=>x&&typeof x==='object').sort((a,b)=>String(b.fecha_revision||'').localeCompare(String(a.fecha_revision||'')))[0];
  const brand=String(latest?.marca||'').slice(0,100),model=String(latest?.modelo||'').slice(0,100);
  if(!brand&&!model){out.textContent='No hay marca/modelo disponibles para esta patente en la fuente consultada.';return;}
  const oldBrand=document.querySelector('#v_brand'),oldModel=document.querySelector('#v_model');
  if(brand)oldBrand.value=brand;if(model)oldModel.value=model;
  out.textContent=`Datos encontrados: ${[brand,model].filter(Boolean).join(' ')}. Fuente: historial PRT vía api.restart.cl. Revisa que corresponda a tu vehículo.`;
 }catch(err){out.textContent='No fue posible consultar esta patente desde el navegador ('+(err.name==='AbortError'?'tiempo agotado':err.message)+'). Puedes adjuntar el padrón y usar OCR o completar los campos manualmente.';}
 finally{clearTimeout(timer);if(btn)btn.disabled=false;}
}
function showUploadModal(){state.uploadFiles=[];state.analyses=[];state.processing=false;state.uploadTarget=state.selected||'new';const choices=state.vehicles.map(v=>`<option value="${escapeHTML(v.id)}" ${v.id===state.selected?'selected':''}>${escapeHTML(v.plate)} · ${escapeHTML([v.brand,v.model].join(' '))}</option>`).join('');const body=`<div class="modal-body"><div class="form-grid two"><div class="form-group"><label for="uploadTarget">Asignar documentos a</label><select id="uploadTarget"><option value="new" ${!state.selected?'selected':''}>+ Crear vehículo desde documento</option>${choices}</select></div><div id="uploadPlateGroup" class="form-group" ${state.selected?'hidden':''}><label for="uploadNewPlate">Patente del nuevo auto *</label><input id="uploadNewPlate" type="text" placeholder="Ej. ABCD12" maxlength="8"/><span class="field-hint">Se completará si el OCR la encuentra.</span></div></div><label class="upload-drop" id="uploadDrop"><input id="uploadFiles" type="file" multiple accept=".pdf,.png,.jpg,.jpeg,.webp,.txt,application/pdf,image/png,image/jpeg,image/webp,text/plain" />${ic('upload',32)}<strong>Seleccionar PDF, foto o documento</strong><small>PDF, JPG, PNG, WebP o TXT · Pulsa Ver para comprobar el original · 25 MB máximo</small></label><div id="uploadFileList" class="upload-file-list"></div><div class="form-grid two"><div class="form-group"><label for="uploadType">Tipo de documento</label><select id="uploadType"><option value="auto">Reconocer automáticamente</option>${DOC_TYPES.map(t=>`<option value="${t.value}">${t.label}</option>`).join('')}</select></div><div class="form-group"><label for="uploadExpiry">Vencimiento (opcional)</label><input id="uploadExpiry" type="date"/><span class="field-hint">Si se ingresa, se aplica a todos los archivos.</span></div></div><div class="tip">${ic('info')}<div>La identificación funciona con texto digital del PDF y OCR en fotografías o escaneos. Reconoce lo que aparece en el documento, no consulta una base de datos de patentes. Revisa los resultados: pueden existir errores.</div></div><div id="ocrProgress" hidden><p id="ocrProgressText" class="processing-hint">Preparando lectura...</p><div class="progress-track"><div class="progress-fill" id="ocrProgressFill"></div></div></div><div id="ocrPreview"></div></div>`;const footer=`<div class="modal-foot"><button class="btn btn-secondary" data-action="analyze">${ic('spark')} Leer con OCR</button><button class="btn btn-secondary" id="cancelOCR" data-action="cancel-ocr" hidden>Detener lectura</button><div class="modal-foot-right"><button class="btn btn-secondary" data-action="close-modal">Cancelar</button><button class="btn btn-primary" data-action="save-upload">${ic('save')} Guardar archivos</button></div></div>`;modalShell('Subir y reconocer documentos','Al elegir los archivos comienza la lectura automática. Puedes corregir los datos antes de guardarlos.',body,footer);renderUploadList();}
function renderUploadList(){const el=document.querySelector('#uploadFileList');if(!el)return;el.innerHTML=state.uploadFiles.map((f,i)=>{const a=state.analyses[i];return `<div class="upload-item">${ic('file')}<div style="flex:1;min-width:0"><strong>${escapeHTML(f.name)}</strong><small>${bytes(f.size)}${a?` · ${escapeHTML(docLabel(a.type))}`:''}</small></div>${a?`<span class="status ${a.error?'bad':a.text?.trim()?'good':'warn'}">${a.error?'Error OCR':a.text?.trim()?'Texto leído':'Sin texto'}</span>`:''}<button type="button" class="btn btn-secondary btn-sm" data-action="preview-upload" data-index="${i}">${ic('external',14)} Ver</button></div>`;}).join('');}
function showAnalysisPreview(){
 const el=document.querySelector('#ocrPreview');if(!el)return;
 const fields={};for(const item of state.analyses)for(const [key,value] of Object.entries(item.fields||{}))if(!fields[key]&&value)fields[key]=value;
 const keyFields=['plate','brand','model','year','kind','color','fuel','vin','chassis','engine','displacement','version','transmission','owner','rut','mileage'];
 const form=keyFields.map(key=>{const label=VEHICLE_FIELDS.find(x=>x[0]===key)?.[1]||key;
 return `<div class="form-group"><label for="ocr_${key}">${escapeHTML(label)} ${fields[key]?'✓':''}</label><input id="ocr_${key}" data-ocr-field="${key}" value="${escapeHTML(fields[key]||'')}" placeholder="${fields[key]?'':'No detectado · completar si corresponde'}" autocomplete="off"></div>`;}).join('');
 el.innerHTML=state.analyses.length?`<section class="ocr-preview"><div class="ocr-review-header"><h4>${ic('spark',18)} Ficha extraída de tus archivos</h4><span class="status ${Object.keys(fields).length?'good':'warn'}">${Object.keys(fields).length} datos detectados</span></div><p class="ocr-warning">Comprueba los valores antes de guardar. Puedes corregir y escribir los que no se detectaron; no se inventan campos.</p><div class="ocr-review">${form}</div>
 <label class="checkline"><input type="checkbox" id="overwriteRecognized"> Reemplazar los datos ya guardados en mi auto con esta ficha revisada</label>
 <details class="ocr-details"><summary>Ver el texto original detectado y errores</summary>${state.analyses.map((a,i)=>`<div><strong>${escapeHTML(state.uploadFiles[i]?.name||'Archivo')}</strong>${a.error?`<p class="danger-text">${escapeHTML(a.error)}</p>`:''}${a.warnings?.map(w=>`<p>${escapeHTML(w)}</p>`).join('')||''}<pre>${escapeHTML(a.text||'No hay texto extraído.')}</pre></div>`).join('')}</details></section>`:'';
 if(fields.plate&&document.querySelector('#uploadTarget')?.value==='new'&&!document.querySelector('#uploadNewPlate')?.value)document.querySelector('#uploadNewPlate').value=fields.plate;
}
function showEditDocument(id){const d=state.docs.find(x=>x.id===id);if(!d)return;const body=`<form id="docForm" data-id="${escapeHTML(d.id)}"><div class="modal-body"><div class="form-grid two"><div class="form-group wide"><label for="docTitle">Nombre del documento</label><input id="docTitle" name="title" value="${escapeHTML(d.title)}" required maxlength="180"/></div><div class="form-group"><label for="docType">Categoría</label><select id="docType" name="type">${DOC_TYPES.map(t=>`<option value="${t.value}" ${t.value===d.type?'selected':''}>${t.label}</option>`).join('')}</select></div><div class="form-group"><label for="docExpires">Fecha de vencimiento</label><input id="docExpires" name="expires" type="date" value="${escapeHTML(d.expires||'')}"/></div><div class="form-group"><label for="docIssued">Fecha de emisión</label><input id="docIssued" name="issued" type="date" value="${escapeHTML(d.issued||'')}"/></div></div><div class="banner-muted">Archivo original: <strong>${escapeHTML(d.filename)}</strong><br/>${bytes(d.size)}. Esta ventana edita los metadatos, no el documento adjunto.</div></div><div class="modal-foot"><button type="button" class="btn btn-secondary" data-action="open-doc" data-id="${escapeHTML(d.id)}">${ic('external')} Ver archivo</button><div class="modal-foot-right"><button type="button" class="btn btn-secondary" data-action="close-modal">Cancelar</button><button type="submit" class="btn btn-primary">${ic('save')} Guardar cambios</button></div></div></form>`;modalShell('Editar documento','Corrige la categoría y las fechas de este archivo.',body);}
function askDelete(kind,id){const isCar=kind==='car';const target=isCar?state.vehicles.find(x=>x.id===id):kind==='fuel'?state.fuelLogs.find(x=>x.id===id):kind==='expense'?state.expenses.find(x=>x.id===id):state.docs.find(x=>x.id===id);if(!target)return;state.confirm={kind,id};const n=isCar?`${target.plate}, sus ${vDocs(id).length} documentos, ${vFuel(id).length} recargas y ${vExpenses(id).length} gastos`:kind==='fuel'?`la carga de ${money(target.total)} del ${fmt(target.date)}`:kind==='expense'?`el gasto de ${money(target.amount)} del ${fmt(target.date)}`:target.filename;modalShell('Confirmar eliminación',`Se eliminará definitivamente ${n}. Esta acción no se puede deshacer.`,`<div class="modal-body"><div class="tip">${ic('alert')} <div>Antes de borrar, considera exportar un respaldo desde la sección de privacidad.</div></div></div>`,`<div class="modal-foot"><button class="btn btn-secondary" data-action="close-modal">Cancelar</button><button class="btn btn-danger" data-action="confirm-delete">${ic('trash')} Eliminar definitivamente</button></div>`,true);}

function progressUser(index,pct,message){const track=document.querySelector('#ocrProgress');if(!track)return;track.hidden=false;const label=document.querySelector('#ocrProgressText');label.textContent=message||(index===null?'Leyendo...':`Leyendo documento ${index+1}...`);if(pct!==null)document.querySelector('#ocrProgressFill').style.width=Math.min(100,Math.max(0,pct))+'%';}
async function extractText(file,index){return await scanVehicleFile(file,(message,pct)=>progressUser(index,pct,message));}
async function analyzeUpload(){if(state.processing)return;if(!state.uploadFiles.length){toast('Selecciona al menos un archivo.');return;}state.processing=true;const run=++state.scanToken;state.analyses=[];document.querySelector('#cancelOCR')?.removeAttribute('hidden');document.querySelectorAll('[data-action="analyze"],[data-action="save-upload"],[data-action="close-modal"],#uploadFiles').forEach(x=>x.disabled=true);let success=0;for(let i=0;i<state.uploadFiles.length;i++){
  const file=state.uploadFiles[i];progressUser(i,Math.round(i/state.uploadFiles.length*100),`Leyendo ${i+1} de ${state.uploadFiles.length}: ${file.name}`);
  try{const result=await Promise.race([extractText(file,i),new Promise((_,reject)=>setTimeout(()=>reject(new Error('Tiempo de lectura agotado. Intenta con una imagen más nítida o guarda el archivo manualmente.')),90000))]);if(run!==state.scanToken)return;const parsed=analyzeDocument(result.text,file.name);state.analyses.push({...parsed,text:result.text.slice(0,20000),warnings:result.warnings,fileName:file.name});success++;}catch(e){state.analyses.push({fields:{},type:analyzeDocument('',file.name).type,expires:'',issued:'',text:'',error:e.message});}
  if(run!==state.scanToken)return;renderUploadList();
 }if(run!==state.scanToken)return;state.processing=false;document.querySelector('#cancelOCR')?.setAttribute('hidden','');progressUser(null,100,`${success}/${state.uploadFiles.length} archivo(s) leídos. Revisa la ficha antes de guardar.`);document.querySelectorAll('[data-action="analyze"],[data-action="save-upload"],[data-action="close-modal"],#uploadFiles').forEach(x=>x.disabled=false);showAnalysisPreview();if(success===0)toast('No se pudo extraer texto. Puedes guardar igualmente los archivos y completar la ficha manualmente.',true);else toast(`Lectura terminada: ${success} documento(s) procesados.`);
}
function cancelOCR(){if(!state.processing)return;state.scanToken++;state.processing=false;document.querySelector('#cancelOCR')?.setAttribute('hidden','');document.querySelectorAll('[data-action="analyze"],[data-action="save-upload"],[data-action="close-modal"],#uploadFiles').forEach(x=>x.disabled=false);document.querySelector('#ocrProgressText').textContent='Lectura detenida. Puedes guardar los archivos sin OCR o intentar nuevamente.';renderUploadList();showAnalysisPreview();toast('Lectura detenida. Los archivos siguen seleccionados.');}
async function saveUploads(){if(state.processing)return;const target=document.querySelector('#uploadTarget')?.value||'new';if(!state.uploadFiles.length){toast('Primero selecciona uno o más archivos.',true);return;}const plate=cleanPlate(document.querySelector('#uploadNewPlate')?.value||'');if(target==='new'&&!validPlate(plate)){toast('Escribe una patente válida (ej. ABCD12 o AB1234) para crear el vehículo.',true);document.querySelector('#uploadNewPlate')?.focus();return;}
 let car=state.vehicles.find(x=>x.id===target);const found={};state.analyses.forEach(a=>Object.entries(a.fields||{}).forEach(([k,v])=>{if(!found[k]&&v)found[k]=v;}));document.querySelectorAll('[data-ocr-field]').forEach(el=>{found[el.dataset.ocrField]=el.value.trim().slice(0,120);});if(found.plate)found.plate=cleanPlate(found.plate);
 if(target==='new'){
  const existing=state.vehicles.find(v=>v.plate===plate);if(existing){toast('Esa patente ya existe. Selecciónala en la lista para adjuntar sus documentos.',true);return;}
  car={id:uid(),...found,plate,updatedAt:new Date().toISOString(),createdAt:new Date().toISOString()};await transaction('vehicles','put',car);
 }else if(car){const patch={};for(const [k,v] of Object.entries(found))if(k!=='plate'&&v&&(document.querySelector('#overwriteRecognized')?.checked||!car[k]))patch[k]=v;car={...car,...patch,updatedAt:new Date().toISOString()};await transaction('vehicles','put',car);}else{toast('No se encontró el vehículo seleccionado.',true);return;}
 const overriddenType=document.querySelector('#uploadType').value;const overriddenExpiry=document.querySelector('#uploadExpiry').value;let count=0;
 for(let i=0;i<state.uploadFiles.length;i++){const f=state.uploadFiles[i];const analysis=state.analyses[i]||{};const type=overriddenType==='auto'?(analysis.type||analyzeDocument('',f.name).type):overriddenType;const doc={id:uid(),vehicleId:car.id,filename:f.name,title:docLabel(type),type,expires:overriddenExpiry||analysis.expires||'',issued:analysis.issued||'',size:f.size,mime:f.type||'application/octet-stream',uploadedAt:new Date().toISOString(),recognized:analysis.fields||{},ocrText:analysis.text||'',ocrError:analysis.error||'',blob:f};await transaction('docs','put',doc);count++;}
 state.selected=car.id;closeModal();state.tab='documentos';await reload();toast(`${count} documento(s) guardado(s) en ${car.plate}. Revisa los datos y vencimientos.`);
}
function openDocument(id){const d=state.docs.find(x=>x.id===id);if(!d?.blob){toast('No se encontró el archivo adjunto.',true);return;}showBlobPreview(d.blob,d.filename,d.mime);}
const base64=blob=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(reader.error);reader.readAsDataURL(blob);});
function fromBase64(s,mime){const raw=atob(s);const arr=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)arr[i]=raw.charCodeAt(i);return new Blob([arr],{type:mime||'application/octet-stream'});}
async function exportBackup(){if(!state.vehicles.length&&!state.docs.length){toast('No hay información para respaldar.');return;}toast('Preparando copia con los documentos adjuntos...');const allDocs=[];for(const d of state.docs){const {blob,...meta}=d;allDocs.push({...meta,base64:await base64(blob)});}const obj={format:'SNK_GARAGE_BACKUP',version:2,exportedAt:new Date().toISOString(),vehicles:state.vehicles,docs:allDocs,fuelLogs:state.fuelLogs,expenses:state.expenses};const file=new Blob([JSON.stringify(obj)],{type:'application/json'});const url=URL.createObjectURL(file);const a=document.createElement('a');a.href=url;a.download=`SNK_Garage_respaldo_${today()}.json`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);toast('Respaldo exportado. Guárdalo en un lugar seguro.');}
async function importBackup(file){if(!file)return;if(file.size>250*1024*1024)throw Error('El respaldo supera 250 MB.');const data=JSON.parse(await file.text());if(data.format!=='SNK_GARAGE_BACKUP'||!Array.isArray(data.vehicles)||!Array.isArray(data.docs)||data.vehicles.length>500||data.docs.length>2000)throw Error('Archivo de respaldo no válido o demasiado grande.');const map=new Map();const docMap=new Map();const oldPlate=new Set(state.vehicles.map(v=>v.plate));let cars=0,docs=0,fuels=0,costs=0;
 for(const v of data.vehicles){if(typeof v!=='object'||!v)continue;const oldId=v.id;const id=uid();const plate=cleanPlate(v.plate);if(!validPlate(plate))continue;if(oldPlate.has(plate)){const existing=state.vehicles.find(x=>x.plate===plate);if(existing){map.set(oldId,existing.id);continue;}}const car={...v,id,plate,updatedAt:new Date().toISOString()};await transaction('vehicles','put',car);map.set(oldId,id);oldPlate.add(plate);cars++;}
 for(const d of data.docs){if(typeof d!=='object'||!d||!map.has(d.vehicleId)||typeof d.base64!=='string')continue;const {base64:encoded,...meta}=d;if(encoded.length>40*1024*1024)continue;const item={...meta,id:uid(),vehicleId:map.get(d.vehicleId),filename:String(d.filename||'archivo'),title:String(d.title||'Documento'),type:DOC_TYPES.some(t=>t.value===d.type)?d.type:'otro',blob:fromBase64(encoded,d.mime)};await transaction('docs','put',item);docMap.set(d.id,item.id);docs++;}
 for(const item of (Array.isArray(data.fuelLogs)?data.fuelLogs:[]).slice(0,20000)){if(!item||!map.has(item.vehicleId)||!positive(item.liters)||!positive(item.total)||!/^\d{4}-\d{2}-\d{2}$/.test(item.date||''))continue;await transaction('fuelLogs','put',{...item,id:uid(),vehicleId:map.get(item.vehicleId),receiptId:docMap.get(item.receiptId)||''});fuels++;}
 for(const item of (Array.isArray(data.expenses)?data.expenses:[]).slice(0,20000)){if(!item||!map.has(item.vehicleId)||!positive(item.amount)||!/^\d{4}-\d{2}-\d{2}$/.test(item.date||''))continue;await transaction('expenses','put',{...item,id:uid(),vehicleId:map.get(item.vehicleId)});costs++;}
 await reload();toast(`Respaldo importado: ${cars} vehículo(s), ${docs} archivo(s), ${fuels} cargas y ${costs} gastos.`);
}

// Finanzas y combustible: solamente datos ingresados por el propietario.
const optionTag=(items,selected='')=>items.map(x=>`<option value="${escapeHTML(x.value)}" ${x.value===selected?'selected':''}>${escapeHTML(x.label)}</option>`).join('');
const safeNum=v=>Number.isFinite(Number(v))?Number(v):0;
const inputVal=(v)=>v===null||v===undefined?'':escapeHTML(v);
function renderBudget(label,current,amount,v){
 if(!positive(amount))return `<div class="budget-box"><div><span>${escapeHTML(label)}</span><strong>Sin presupuesto definido</strong></div><button class="text-link" data-action="edit-car" data-id="${escapeHTML(v.id)}">Definir tope mensual ${ic('arrow',13)}</button></div>`;
 const max=Number(amount),ratio=current/max,remaining=Math.max(0,max-current);
 return `<div class="budget-box"><div class="budget-heading"><div><span>${escapeHTML(label)}</span><strong>${money(current)} <small>de ${money(max)}</small></strong></div><div class="budget-right ${ratio>1?'over':''}">${ratio>1?`Excedido por ${money(current-max)}`:`Disponible ${money(remaining)}`}</div></div><div class="budget-progress"><div class="${ratio>1?'over':''}" style="width:${Math.min(100,Math.round(ratio*100))}%"></div></div><div class="budget-footer"><span>${Math.round(ratio*100)}% utilizado este mes</span><button class="text-link" data-action="edit-car" data-id="${escapeHTML(v.id)}">Editar presupuesto</button></div></div>`;
}
