function renderPlate(v){return `<div class="identity-bar"><div class="license"><small>REPÚBLICA DE CHILE</small><strong>${escapeHTML(v.plate||'SIN PATENTE')}</strong><span>CHILE</span></div><div><div class="eyebrow">IDENTIFICACIÓN VEHICULAR</div><h2>${escapeHTML([v.brand,v.model,v.version].filter(Boolean).join(' ')||'Mi vehículo')}</h2><p>${escapeHTML(v.year||'Año sin registrar')} · ${escapeHTML(v.fuel||'Tipo de combustible sin registrar')}</p><div class="tag-fuel">${ic('fuel',15)} ${escapeHTML(fuelName(v.fuelGrade))}</div></div><button class="btn btn-secondary" data-action="edit-car" data-id="${escapeHTML(v.id)}">${ic('edit')} Cambiar octanaje</button></div>`;}
function fuelRow(log){const v=state.vehicles.find(x=>x.id===log.vehicleId);return `<article class="transaction-row"><div class="trans-icon">${ic('fuel',20)}</div><div class="trans-main"><strong>${money(log.total)} <span class="trans-soft">· ${quantity(log.liters,2)} L</span></strong><small>${fmt(log.date)} · ${escapeHTML(fuelName(log.grade))} ${log.station?' · '+escapeHTML(log.station):''}</small><small>${log.odometer?quantity(log.odometer,0)+' km':'Kilometraje no indicado'} · ${money(Math.round(safeNum(log.total)/safeNum(log.liters)))} / L ${log.fullTank?' · Tanque lleno':''} ${v?.id!==state.selected?' · '+escapeHTML(v?.plate||''):''}</small></div><div class="trans-actions">${log.receiptId&&state.docs.find(x=>x.id===log.receiptId)?`<button class="icon-action" data-action="open-doc" data-id="${escapeHTML(log.receiptId)}" title="Ver comprobante" aria-label="Ver comprobante">${ic('file')}</button>`:''}<button class="icon-action" data-action="fuel-edit" data-id="${escapeHTML(log.id)}" title="Editar carga" aria-label="Editar carga">${ic('edit')}</button><button class="icon-action" data-action="fuel-delete" data-id="${escapeHTML(log.id)}" title="Borrar carga" aria-label="Borrar carga">${ic('trash')}</button></div></article>`;}
function expenseRow(item){return `<article class="transaction-row"><div class="trans-icon">${ic('receipt',20)}</div><div class="trans-main"><strong>${money(item.amount)} <span class="trans-soft">· ${escapeHTML(expenseName(item.category))}</span></strong><small>${fmt(item.date)} ${item.title?' · '+escapeHTML(item.title):''}</small>${item.notes?`<small>${escapeHTML(item.notes)}</small>`:''}</div><div class="trans-actions"><button class="icon-action" data-action="expense-edit" data-id="${escapeHTML(item.id)}" title="Editar gasto" aria-label="Editar gasto">${ic('edit')}</button><button class="icon-action" data-action="expense-delete" data-id="${escapeHTML(item.id)}" title="Borrar gasto" aria-label="Borrar gasto">${ic('trash')}</button></div></article>`;}
function renderMonthBars(id){const months=monthlySeries(state.fuelLogs,state.expenses,id);const max=Math.max(1,...months.map(x=>x.total));return `<div class="month-chart" role="img" aria-label="Comparación de gastos de los últimos seis meses">${months.map(x=>`<div class="month-col"><div class="month-amount">${x.total?money(x.total):'—'}</div><div class="month-stack" title="${escapeHTML(x.month)}: Bencina ${money(x.fuelCLP)}, otros ${money(x.otherCLP)}"><div class="bar-fuel" style="height:${Math.round(x.fuelCLP/max*100)}%"></div><div class="bar-other" style="height:${Math.round(x.otherCLP/max*100)}%"></div></div><small>${escapeHTML(x.label)}</small></div>`).join('')}</div><div class="chart-key"><span><b class="key-square fuel-color"></b> Combustible</span><span><b class="key-square other-color"></b> Otros gastos</span></div>`;}
function renderFuel(){const v=vehicle();if(!v)return `<div class="page-head"><div><div class="eyebrow">CONTROL DEL VEHÍCULO</div><h1 class="page-title">Combustible y recargas</h1><p class="page-copy">Registra litros, precio y kilómetros para controlar cuánto gastas.</p></div></div>${empty('Necesitas registrar un vehículo','Primero ingresa su patente y luego podrás llevar su historial de cargas.','Crear vehículo')}`;
 const logs=vFuel();const all=periodSummary(state.fuelLogs,state.expenses,v.id);const month=periodSummary(state.fuelLogs,state.expenses,v.id,today().slice(0,7));const eff=consumption(state.fuelLogs,v.id);
 return `<div class="page-head"><div><div class="eyebrow">CONTROL DE COMBUSTIBLE</div><h1 class="page-title">Bencina y recargas</h1><p class="page-copy">Todas las cargas de ${escapeHTML(v.plate)}: dinero, octanaje, kilómetros y consumo estimado.</p></div><div class="page-head-actions"><button class="btn btn-secondary" data-action="csv-fuel">${ic('download')} CSV</button><button class="btn btn-primary" data-action="fuel-new">${ic('plus')} Nueva carga</button></div></div>
 ${renderPlate(v)}${renderBudget('Presupuesto de combustible · mes actual',month.fuelCLP,v.fuelBudget,v)}
 <div class="stats-grid">${stat('Gasto en combustible',money(all.fuelCLP),'Total histórico','wallet')}${stat('Este mes',money(month.fuelCLP),`${month.fillCount} carga(s)`,'calendar')}${stat('Litros cargados',quantity(all.liters,2)+' L','Histórico','fuel')}${stat('Precio promedio',all.averagePricePerLiter?money(Math.round(all.averagePricePerLiter)):'—','Por litro (ponderado)','trend')}</div>
 <div class="split-grid"><section class="panel"><div class="panel-top"><h3>Rendimiento calculado</h3><span class="status neutral">Tanque lleno a tanque lleno</span></div><div class="efficiency-grid"><div><small>Rendimiento</small><strong>${eff?quantity(eff.kmPerLiter,2)+' km/L':'—'}</strong></div><div><small>Consumo</small><strong>${eff?quantity(eff.litersPer100,2)+' L/100 km':'—'}</strong></div><div><small>Costo combustible</small><strong>${eff?money(Math.round(eff.costPerKm))+'/km':'—'}</strong></div></div><p class="hint-plain">${eff?`Basado en ${eff.intervals} intervalo(s) entre recargas marcadas como tanque lleno, con odómetro registrado.`:'Para calcular km/L de forma útil, registra al menos dos cargas con «Tanque lleno» y su kilometraje. Se sumarán también las recargas intermedias.'}</p></section><section class="panel"><div class="panel-top"><h3>Gasto de combustible y otros</h3><button class="text-link" data-nav="gastos">Ver gastos ${ic('arrow',13)}</button></div>${renderMonthBars(v.id)}</section></div>
 <div class="section-head"><h2 class="section-title">Historial de cargas · ${logs.length}</h2></div>${logs.length?`<div class="transaction-list">${logs.map(fuelRow).join('')}</div>`:empty('Todavía no registras bencina','Ingresa los litros y el total pagado. El sistema calcula precio por litro y permite estimar el consumo.','Registrar primera carga','fuel-new','fuel')}`;
}
function renderExpenses(){const v=vehicle();if(!v)return `<div class="page-head"><div><h1 class="page-title">Gastos del auto</h1></div></div>${empty('Registra un auto para empezar','Así podrás controlar mantenciones, TAG, seguros y gastos.','Registrar vehículo')}`;
 const all=periodSummary(state.fuelLogs,state.expenses,v.id);const month=periodSummary(state.fuelLogs,state.expenses,v.id,today().slice(0,7));const costs=vExpenses();
 return `<div class="page-head"><div><div class="eyebrow">FINANZAS DEL AUTO</div><h1 class="page-title">Gastos y presupuesto</h1><p class="page-copy">Combustible, mantenciones, peajes, repuestos, seguros y otros pagos del vehículo ${escapeHTML(v.plate)}.</p></div><div class="page-head-actions"><button class="btn btn-secondary" data-action="csv-expenses">${ic('download')} CSV gastos</button><button class="btn btn-primary" data-action="expense-new">${ic('plus')} Agregar gasto</button></div></div>${renderPlate(v)}${renderBudget('Presupuesto total · mes actual',month.total,v.totalBudget,v)}
 <div class="stats-grid">${stat('Gastos acumulados',money(all.total),'Todos los registros','wallet')}${stat('Gastos este mes',money(month.total),'Bencina y otros pagos','calendar')}${stat('Combustible histórico',money(all.fuelCLP),'Recargas realizadas','fuel')}${stat('Otros pagos históricos',money(all.otherCLP),'Sin incluir bencina','receipt')}</div>
 <div class="split-grid"><section class="panel"><div class="panel-top"><h3>Resumen por categoría</h3></div>${[{label:'Bencina / diésel',value:all.fuelCLP},...EXPENSE_TYPES.map(x=>({label:x.label,value:costs.filter(c=>c.category===x.value).reduce((sum,c)=>sum+safeNum(c.amount),0)}))].filter(x=>x.value>0).sort((a,b)=>b.value-a.value).map(x=>`<div class="cost-cat"><span>${escapeHTML(x.label)}</span><strong>${money(x.value)}</strong><div class="category-track"><div style="width:${Math.round(x.value/Math.max(1,all.total)*100)}%"></div></div></div>`).join('')||'<p class="hint-plain">Todavía no has registrado gastos.</p>'}</section><section class="panel"><div class="panel-top"><h3>Evolución de los últimos 6 meses</h3></div>${renderMonthBars(v.id)}</section></div>
 <div class="section-head"><h2 class="section-title">Otros gastos · ${costs.length}</h2><button class="btn btn-secondary btn-sm" data-nav="combustible">${ic('fuel')} Ver recargas</button></div>${costs.length?`<div class="transaction-list">${costs.map(expenseRow).join('')}</div>`:empty('Sin gastos adicionales','Puedes agregar reparaciones, aceite, seguro, lavado, estacionamiento y más. Las cargas se registran por separado.','Agregar primer gasto','expense-new','receipt')}`;
}
